class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is ComputeUnitKindMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is ScalarTypeMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is ValueKindMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is ValueRoleMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is SpecializationPresetMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    } else if (value is ImageEncodingMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is SpecializationOptionsMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is SpecializationInfoMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is ModelCacheMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is CachePolicyMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is InterleaveLayoutMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is NDArrayDescriptorMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is ImageDescriptorMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is ValueDescriptorMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is FunctionDescriptorMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is ModelInfoMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is FunctionInfoMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is NDArrayMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is PixelBufferPlaneMessage) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is PixelBufferMessage) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is NativeValueRefMessage) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    } else if (value is NativeValueInfoMessage) {
      buffer.putUint8(150);
      writeValue(buffer, value.encode());
    } else if (value is RunRequestMessage) {
      buffer.putUint8(151);
      writeValue(buffer, value.encode());
    } else if (value is RunResultMessage) {
      buffer.putUint8(152);
      writeValue(buffer, value.encode());
    } else if (value is EncodeRequestMessage) {
      buffer.putUint8(153);
      writeValue(buffer, value.encode());
    } else if (value is AssetMetadataMessage) {
      buffer.putUint8(154);
      writeValue(buffer, value.encode());
    } else if (value is AssetMetadataUpdateMessage) {
      buffer.putUint8(155);
      writeValue(buffer, value.encode());
    } else if (value is AssetValueDescriptorMessage) {
      buffer.putUint8(156);
      writeValue(buffer, value.encode());
    } else if (value is AssetFunctionDescriptorMessage) {
      buffer.putUint8(157);
      writeValue(buffer, value.encode());
    } else if (value is NamedCountMessage) {
      buffer.putUint8(158);
      writeValue(buffer, value.encode());
    } else if (value is AssetSummaryMessage) {
      buffer.putUint8(159);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : ComputeUnitKindMessage.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : ScalarTypeMessage.values[value];
      case 131:
